INSERT INTO `products` (`id`, `url`, `name`, `podcategory`, `price`, `power`, `tags`, `proizvoditel`, `city`, `main_photo`, `characteristics`, `description`, `meta`, `bunker`, `razmer`, `gabaryte`, `komplect`, `reviews`, `nomer`, `document`, `video`, `ves`, `category`, `gorelka`, `tipteploobmennika`, `napravlenie`, `kolichestvo`, `diametrdymohoda`, `ehlektropodzhig`, `related`) VALUES
(1, 'kotel-roteks-15/', 'Автоматический пеллетный котел Ротекс 15', '<li class=\"breadcrumb__content--menu__items\"><a href=\"/category/pelletnye-kotly/\">Пеллетные автоматические котлы</a></li><li class=\"breadcrumb__content--menu__items\"><a href=\"/category/kotly-roteks-chelyabinsk/\">Пеллетные котлы Ротекс</a></li>', 340000, '15', 'Автоматические котлы с бункером', 'Roteks', 'Челябинск', 'https://modulkotel.ru/assets/img/product/roteks/main.webp', '<table border=\"1\" cellpadding=\"5\" cellspacing=\"0\">\r\n    <thead>\r\n        <tr>\r\n            <th>Параметр</th>\r\n            <th>Значение</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr>\r\n            <td>Номинальная теплопроизводительность (кВт)</td>\r\n            <td>15</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Рабочая температура котла (°C)</td>\r\n            <td>70-90</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Максимальная температура на выходе из котла (°C)</td>\r\n            <td>95</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Минимальная температура на входе в котел (°C)</td>\r\n            <td>60</td>\r\n        </tr>\r\n        <tr>\r\n            <td>КПД котла (%)</td>\r\n            <td>80-90 (зависит от чистоты котла)</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Рабочее давление системы (Бар)</td>\r\n            <td>1,5</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Опрессовочное давление (Бар)</td>\r\n            <td>6</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Подключение к системе отопления (Ду)</td>\r\n            <td>25</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Размер дымохода котла (Ø мм)</td>\r\n            <td>125</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Площадь конвективной части (м²)</td>\r\n            <td>1,8</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Заправочная емкость котла (л)</td>\r\n            <td>40</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Номинальный расход воды (м³/ч)</td>\r\n            <td>0,65</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Масса котла (нетто) (кг)</td>\r\n            <td>385</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Масса котла с водой (кг)</td>\r\n            <td>425</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Масса бункера (нетто) (кг)</td>\r\n            <td>65</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Емкость бункера для гранул (кг)</td>\r\n            <td>130</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Средний расход гранул (кг/ч)</td>\r\n            <td>1,5</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Максимальный расход гранул (кг/ч)</td>\r\n            <td>3,3</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Вид топлива</td>\r\n            <td>Древесные гранулы, влажностью не более 10%, зольностью не более 1%</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Выбросы твердых частиц (г/ч)</td>\r\n            <td>0,0215</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Выбросы СО не более (мг/м³)</td>\r\n            <td>550</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Выбросы NO2 не более (мг/м³)</td>\r\n            <td>120</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Температура уходящих газов (°C)</td>\r\n            <td>110-180</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Расход воздуха, не более (м³/ч)</td>\r\n            <td>19</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Электроподключение (В)</td>\r\n            <td>380 (220 по дополнительному заказу)</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Подключаемая мощность (Эконом/Люкс) (кВт)</td>\r\n            <td>0,3/2,3</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Удельное энергопотребление (Вт*ч)</td>\r\n            <td>50</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Общие габариты при открытых дверцах и люках (высота х глубина х ширина) (мм)</td>\r\n            <td>1600х1415х1330</td>\r\n        </tr>\r\n    </tbody>\r\n</table>', '\r\n<ul>\r\n<li>Дистанционное включение/отключение</li>\r\n<li>SMS-уведомления о работе котла</li>\r\n</ul>', '<fieldset class=\"variant__input--fieldset\">         <legend class=\"product__variant--title mb-8\">Выберите комплектацию:</legend>         <ul class=\"variant__size d-flex\">             <li class=\"variant__size--list\">                 <input id=\"weight4\" name=\"weight\" type=\"radio\" checked=\"\">                 <label class=\"variant__size--value red\" for=\"weight4\">Эконом</label>             </li>             <li class=\"variant__size--list\">                 <input id=\"weight5\" name=\"weight\" type=\"radio\">                 <label class=\"variant__size--value red\" for=\"weight5\">Люкс</label>             </li>         </ul>     </fieldset>      <script>         document.addEventListener(\'DOMContentLoaded\', function() {             const baseLabel = document.querySelector(\'label[for=\"weight4\"]\');             const classicoLabel = document.querySelector(\'label[for=\"weight5\"]\');             const ottimaLabel = document.querySelector(\'label[for=\"weight6\"]\');              baseLabel.addEventListener(\'click\', function() {                 this.textContent = \'340 000,00 ₽\';             });              classicoLabel.addEventListener(\'click\', function() {                 this.textContent = \'380 000,00 ₽\';                              });         });     </script>', '', '1600х1415х1330', '<div class=\"product__tab--content__step style2 d-flex align-items-center mb-30\">    <div class=\"product__tab--content__banner\">        <h3>(Открытые дверцы)</h3>        <br>        <a class=\"product__media--view__icon--link glightbox\" href=\"https://modulkotel.ru/assets/img/categories/roteks/15/1.jpg\" data-gallery=\"product-media-preview\">            <svg class=\"product__items--action__btn--svg\" xmlns=\"http://www.w3.org/150/svg\" width=\"22.51\" height=\"22.443\" viewBox=\"0 0 512 512\">                <path d=\"M221.09 64a157.09 157.09 0 10157.09 157.09A157.1 157.1 0 00221.09 64z\" fill=\"none\" stroke=\"currentColor\" stroke-miterlimit=\"10\" stroke-width=\"32\"></path>                <path fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-miterlimit=\"10\" stroke-width=\"32\" d=\"M338.29 338.29L448 448\"></path>            </svg>            <span class=\"visually-hidden\">product view</span>        </a>        <a class=\"product__media--preview__items--link glightbox\" data-gallery=\"product-media-preview\" href=\"https://modulkotel.ru/assets/img/categories/roteks/15/1.jpg\">            <img class=\"product__tab--content__banner--img border-radius-5\" src=\"https://modulkotel.ru/assets/img/categories/roteks/15/1.jpg\" alt=\"габариты котла ротекс 15 открытые дверцы\">        </a>    </div>    <div class=\"product__tab--content__banner\">        <h3>(Закрытые дверцы)</h3>        <br>        <a class=\"product__media--view__icon--link glightbox\" href=\"https://modulkotel.ru/assets/img/categories/roteks/15/2.jpg\" data-gallery=\"product-media-preview\">            <svg class=\"product__items--action__btn--svg\" xmlns=\"http://www.w3.org/150/svg\" width=\"22.51\" height=\"22.443\" viewBox=\"0 0 512 512\">                <path d=\"M221.09 64a157.09 157.09 0 10157.09 157.09A157.1 157.1 0 00221.09 64z\" fill=\"none\" stroke=\"currentColor\" stroke-miterlimit=\"10\" stroke-width=\"32\"></path>                <path fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-miterlimit=\"10\" stroke-width=\"32\" d=\"M338.29 338.29L448 448\"></path>            </svg>            <span class=\"visually-hidden\">product view</span>        </a>        <a class=\"product__media--preview__items--link glightbox\" data-gallery=\"product-media-preview\" href=\"https://modulkotel.ru/assets/img/categories/roteks/15/2.jpg\">            <img class=\"product__tab--content__banner--img border-radius-5\" src=\"https://modulkotel.ru/assets/img/categories/roteks/15/2.jpg\" alt=\"габариты котла ротекс 15 закрытые дверцы\">        </a>    </div></div><div style=\"text-align: center;\">  <hr class=\"separator\" style=\"width: 15px; height: 8px; background-color: #ed1d24; opacity: 1; margin-bottom: 30px;\"></div><h3>Размер в упаковки котла Ротекс 15</h3><div class=\"blog__thumbnail mb-30\">       <a class=\"product__media--view__icon--link glightbox\" href=\"https://modulkotel.ru/assets/img/categories/roteks/15/3.jpg\" data-gallery=\"Размер в упаковки котла Ротекс 15\">            <svg class=\"product__items--action__btn--svg\" xmlns=\"http://www.w3.org/150/svg\" width=\"22.51\" height=\"22.443\" viewBox=\"0 0 512 512\">                <path d=\"M221.09 64a157.09 157.09 0 10157.09 157.09A157.1 157.1 0 00221.09 64z\" fill=\"none\" stroke=\"currentColor\" stroke-miterlimit=\"10\" stroke-width=\"32\"></path>                <path fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-miterlimit=\"10\" stroke-width=\"32\" d=\"M338.29 338.29L448 448\"></path>            </svg>            <span class=\"visually-hidden\">product view</span>        </a>    <img class=\"blog__thumbnail--img border-radius-10\" src=\"https://modulkotel.ru/assets/img/categories/roteks/15/3.jpg\" alt=\"Размер в упаковки котла Ротекс 15\"></div>', '<p>Rоteks 15 в комплектации Люкс оснащены дополнительным оборудованием,<br />позволяющим дистанционно (с помощью сотового телефона) контролировать и управлять<br />работой котла.</p>\r\n<p>В дополнительный комплект поставки входит:<br />1. GSM модем;<br />2. Антенна;<br />3. Блок питания;<br />4. Соединительный кабель;<br />5. Фен розжига с подающим патрубком.</p>\r\n<p>&nbsp; Комплект GSM модуля устанавливается в ящике управления, а фен розжига внутри короба<br />воздуховода после вентилятора.<br />Для подключения функции SMS оповещения и контроля необходимо:</p>\r\n<p>1. Установить в GSM модем SIM карту с предварительно отключенным PIN кодом и<br />удаленными SMS сообщениями. Убедитесь, что в месте установки котла имеется<br />связь с оператором сотовой связи.</p>\r\n<p>2. В меню &laquo;Установки&raquo; указать номер телефона в формате +7, с<br />которого будет осуществляться управление, и на который будут приходить SMS,<br />отправляемые GSM модемом.</p>\r\n<p>3. В меню &laquo;Установки&raquo; установить значение &laquo;GSM модем&raquo; ВКЛ.</p>', '<ul class=\"rating product__card--rating mb-15 d-flex\">\r\n                  <li class=\"rating__list\">\r\n                      <span class=\"rating__icon\"> \r\n                          <svg width=\"14\" height=\"13\" viewBox=\"0 0 14 13\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\r\n                              <path d=\"M12.4141 4.53125L8.99219 4.03906L7.44531 0.921875C7.1875 0.382812 6.39062 0.359375 6.10938 0.921875L4.58594 4.03906L1.14062 4.53125C0.53125 4.625 0.296875 5.375 0.742188 5.82031L3.20312 8.23438L2.61719 11.6328C2.52344 12.2422 3.17969 12.7109 3.71875 12.4297L6.78906 10.8125L9.83594 12.4297C10.375 12.7109 11.0312 12.2422 10.9375 11.6328L10.3516 8.23438L12.8125 5.82031C13.2578 5.375 13.0234 4.625 12.4141 4.53125ZM9.53125 7.95312L10.1875 11.75L6.78906 9.96875L3.36719 11.75L4.02344 7.95312L1.25781 5.28125L5.07812 4.71875L6.78906 1.25L8.47656 4.71875L12.2969 5.28125L9.53125 7.95312Z\" fill=\"currentColor\"></path>\r\n                          </svg>\r\n                      </span>\r\n                  </li>\r\n                  <li class=\"rating__list\">\r\n                      <span class=\"rating__icon\"> \r\n                          <svg width=\"14\" height=\"13\" viewBox=\"0 0 14 13\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\r\n                              <path d=\"M12.4141 4.53125L8.99219 4.03906L7.44531 0.921875C7.1875 0.382812 6.39062 0.359375 6.10938 0.921875L4.58594 4.03906L1.14062 4.53125C0.53125 4.625 0.296875 5.375 0.742188 5.82031L3.20312 8.23438L2.61719 11.6328C2.52