INSERT INTO `products` (`id`, `url`, `name`, `podcategory`, `price`, `power`, `tags`, `proizvoditel`, `city`, `main_photo`, `characteristics`, `description`, `meta`, `bunker`, `razmer`, `gabaryte`, `komplect`, `reviews`, `nomer`, `document`, `video`, `ves`, `category`, `gorelka`, `tipteploobmennika`, `napravlenie`, `kolichestvo`, `diametrdymohoda`, `ehlektropodzhig`, `related`) VALUES
(319, 'kotel-start-50-long-na-ugle-i-drovah/', 'Котел СТАРТ 50-Long на угле и дровах', '<li class=\"breadcrumb__content--menu__items\"><a href=\"https://modulkotel.ru/category/tverdotoplivnye-kotly/\">Твердотопливные котлы</a></li><li class=\"breadcrumb__content--menu__items\"><a href=\"/category/kotly-start/\">Котлы Старт</a></li>', 1, '50', NULL, 'СТАРТ', 'Челябинск', 'https://modulkotel.ru/wp-content/uploads/2022/10/start50dl-2020-right.jpg', '\r\n					<table width=\"517\"><tbody><tr><td rowspan=\"2\" width=\"351\">Характеристика</td><td width=\"166\">Модель котла</td></tr><tr><td width=\"166\">СТАРТ-50-Long</td></tr><tr><td width=\"351\">Максимальная мощность, кВт</td><td width=\"166\">50</td></tr><tr><td width=\"351\">КПД, %</td><td width=\"166\">86</td></tr><tr><td width=\"351\">Объем топки, л</td><td width=\"166\">120</td></tr><tr><td width=\"351\">Объем воды в котле, л</td><td width=\"166\">140</td></tr><tr><td width=\"351\">Масса котла, кг</td><td width=\"166\">430</td></tr><tr><td width=\"351\">Габаритные размеры установки, мм</td><td width=\"166\"> </td></tr><tr><td width=\"351\"> Высота</td><td width=\"166\">1440</td></tr><tr><td width=\"351\">Ширина</td><td width=\"166\">615</td></tr><tr><td width=\"351\"> Глубина</td><td width=\"166\">760</td></tr><tr><td width=\"351\">Мощность встроенного электрокотла</td><td width=\"166\">18 кВт</td></tr><tr><td width=\"351\">Диаметр дымовой трубы, мм</td><td width=\"166\">150 или 160</td></tr><tr><td rowspan=\"2\" width=\"351\">Максимальная температура воды на выходе</td><td width=\"166\"> </td></tr><tr><td width=\"166\"> </td></tr><tr><td width=\"351\">Максимальная температура окружающей среды блока управления, °С</td><td width=\"166\">50</td></tr><tr><td width=\"351\">Теплоноситель</td><td width=\"166\"> </td></tr><tr><td width=\"351\">Максимальное давление в котле, кгс/см<sup>2</sup></td><td width=\"166\">1,5</td></tr><tr><td width=\"351\">Размер водяных патрубков</td><td width=\"166\">2&#8221;</td></tr><tr><td width=\"351\">Топливо</td><td width=\"166\">Дрова, уголь, деревоотходы</td></tr><tr><td width=\"351\">Напряжение питания и потребляемая мощность</td><td width=\"166\">220В+/-10%, 50Гц, не более 80 Вт (без учета мощности циркуляционного насоса отопления)</td></tr><tr><td width=\"351\">Максимальная мощность циркуляционного насоса</td><td width=\"166\">130 Вт</td></tr><tr><td width=\"351\">Срок службы котла</td><td width=\"166\">не менее 15 лет</td></tr><tr><td colspan=\"2\" width=\"517\">* &#8211; котел способен выдавать до 150 кВт при повышении мощности вентилятора в настройках</td></tr><tr><td colspan=\"2\" width=\"517\">автоматики и использовании качественного топлива.</td></tr></tbody></table>\r\n', 'Цены на котлы СТАРТ без НДС!', '', '', NULL, '', '<p>Комплектация:<br />1) теплообменник с установленной дверкой теплообменника и со снятыми теплоизоляционными панелями;<br />2) теплоизоляционные панели в отдельной картонной упаковке;<br />3) топливный бункер 400 литров;<br />4) механизм подачи (шнек) с горелкой;<br />5) вентилятор WPA06;<br />6) блок управления ТИГРА;<br />7) зольный ящик 16 литров;<br />8) электрический ТЭН 9кВт (220 В) &ndash; 2 шт;<br />9) чугунные колосники 400*250мм &ndash; 2 шт;<br />10) пластины-турбулизаторы &ndash; 14 шт;<br />11) топочная чугунная дверка со стеклянной вставкой;<br />12) комплект саморезов, болтов, гаек и винтов для сборки;<br />13) инструкция по эксплуатации.</p>', '<ul class=\"rating product__card--rating mb-15 d-flex\">\r\n                  <li class=\"rating__list\">\r\n                      <span class=\"rating__icon\"> \r\n                          <svg width=\"14\" height=\"13\" viewBox=\"0 0 14 13\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\r\n                              <path d=\"M12.4141 4.53125L8.99219 4.03906L7.44531 0.921875C7.1875 0.382812 6.39062 0.359375 6.10938 0.921875L4.58594 4.03906L1.14062 4.53125C0.53125 4.625 0.296875 5.375 0.742188 5.82031L3.20312 8.23438L2.61719 11.6328C2.52344 12.2422 3.1