INSERT INTO `products` (`id`, `url`, `name`, `podcategory`, `price`, `power`, `tags`, `proizvoditel`, `city`, `main_photo`, `characteristics`, `description`, `meta`, `bunker`, `razmer`, `gabaryte`, `komplect`, `reviews`, `nomer`, `document`, `video`, `ves`, `category`, `gorelka`, `tipteploobmennika`, `napravlenie`, `kolichestvo`, `diametrdymohoda`, `ehlektropodzhig`, `related`) VALUES
(4743, 'kotel-lavoro-carbone-lc-52/', 'Твердотопливный угольный котел Lavoro Carbone LC-52', '<li class=\"breadcrumb__content--menu__items\"><a href=\"/category/tverdotoplivnye-kotly/\">Твердотопливные котлы</a></li>\r\n<li class=\"breadcrumb__content--menu__items\"><a href=\"/category/tverdotoplivnyy-kotel-lavoro/\">Твердотопливные котлы lavoro</a></li>', 204500, '52', NULL, 'Lavoro', 'Кострома', 'https://modulkotel.ru/assets/img/categories/lavoro/lc.png', '<table>\r\n  <tr>\r\n    <th>Характеристика</th>\r\n    <th>Значение</th>\r\n  </tr>\r\n  <tr>\r\n    <td>Тепловая мощность, кВт</td>\r\n    <td>52</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Площадь отапливаемых помещений, м2</td>\r\n    <td>520</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Блок автоматики</td>\r\n    <td>контроллер Eco100 и дутьевые вентиляторы</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Тип топлива</td>\r\n    <td>Уголь (с теплотой сгорания до 6500 ккал/кг)</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Объём воды в Котле, л</td>\r\n    <td>120</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Диаметр дымохода наружный, мм</td>\r\n    <td>219</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Размер топки, мм</td>\r\n    <td>высота: 580, ширина: 450, глубина: 505</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Размер проема загрузочной камеры (ВхШ), мм</td>\r\n    <td>400 x 450</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Площадь поверхности нагрева, м2</td>\r\n    <td>4.5</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Минимальная тяга дымохода, Па</td>\r\n    <td>25</td>\r\n  </tr>\r\n  <tr>\r\n    <td>КПД при номинальной мощности не менее, %</td>\r\n    <td>83</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Минимальная температура воды обратной линии, ºC</td>\r\n    <td>55</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Максимальная рабочая температура воды на выходе из Котла, °С</td>\r\n    <td>90</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Вид и род тока для энергозависимых Котлов</td>\r\n    <td>переменный, 50 Гц, напряжение 220+ 10 В</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Рабочее давление в гидравлическом контуре Котлов, МПа</td>\r\n    <td>для систем закрытого типа: 0.25, для систем открытого типа: 0.15</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Масса Котла, кг</td>\r\n    <td>460</td>\r\n  </tr>\r\n</table>', NULL, '', '', '1667x760x1150', '<div class=\"product__tab--content__step style2 d-flex align-items-center mb-30\">\r\n    <!-- Первый баннер с изображением -->\r\n    <div class=\"product__tab--content__banner\">\r\n        <h3>рис 1</h3>\r\n        <br>\r\n        <a class=\"product__media--view__icon--link glightbox\" href=\"https://modulkotel.ru/assets/img/categories/lavoro/gab/carbon/1.png\" data-gallery=\"product-media-preview\">\r\n            <svg class=\"product__items--action__btn--svg\" xmlns=\"http://www.w3.org/150/svg\" width=\"22.51\" height=\"22.443\" viewBox=\"0 0 512 512\">\r\n                <path d=\"M221.09 64a157.09 157.09 0 10157.09 157.09A157.1 157.1 0 00221.09 64z\" fill=\"none\" stroke=\"currentColor\" stroke-miterlimit=\"10\" stroke-width=\"32\"></path>\r\n                <path fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-miterlimit=\"10\" stroke-width=\"32\" d=\"M338.29 338.29L448 448\"></path>\r\n            </svg>\r\n            <span class=\"visually-hidden\">product view</span>\r\n        </a>\r\n        <a class=\"product__media--preview__items--link glightbox\" data-gallery=\"product-media-preview\" href=\"https://modulkotel.ru/assets/img/categories/lavoro/gab/carbon/1.png\">\r\n            <img class=\"product__tab--content__banner--img border-radius-5\" src=\"https://modulkotel.ru/assets/img/categories/lavoro/gab/carbon/1.png\" alt=\"габариты котла Lavoro 15 открытые дверцы\">\r\n        </a>\r\n    </div>\r\n</div>\r\n\r\n<!-- Разделитель -->\r\n<div style=\"text-align: center;\">\r\n    <hr class=\"separator\" style=\"width: 15px; height: 8px; background-color: #ed1d24; opacity: 1; margin-bottom: 30px;\">\r\n</div>\r\n\r\n<!-- Заголовок таблицы размеров -->\r\n<h4>Таблицы размеров</h4>\r\n<div class=\"bl